B = 1000


class Node:
    __slots__ = ("size", "nxt", "d")

    def __init__(self):
        self.size = 0
        self.nxt = None
        self.d = []


class BlockList:
    """块状链表：支持按位置 find/insert/delete，均摊 O(√n)。
    B 为块大小常量。实现定位 + 满块分裂。
    """

    def __init__(self, init=""):
        self.head = Node()
        for ch in init:
            self.push_back(ch)

    def push_back(self, ch):
        if self.head is None:
            self.head = Node()
        p = self.head
        while p.nxt is not None:
            p = p.nxt
        p.d.append(ch)
        p.size += 1
        if p.size >= 2 * B:
            self.split(p)

    def _locate(self, pos):
        """返回 (节点, 块内下标)，定位第 pos 个元素(0-index)。"""
        p = self.head
        while p is not None and pos >= p.size:
            pos -= p.size
            p = p.nxt
        return p, pos

    def split(self, x):
        if x.size < 2 * B:
            return
        y = Node()
        y.d = x.d[B:]
        y.size = len(y.d)
        del x.d[B:]
        x.size = len(x.d)
        y.nxt = x.nxt
        x.nxt = y

    def find(self, pos):
        p, i = self._locate(pos)
        return p.d[i]

    def insert(self, pos, ch):
        if self._size() == 0:
            self.head = Node()
            self.head.d.append(ch)
            self.head.size = 1
            return
        if pos == self._size():
            self.push_back(ch)
            return
        p, i = self._locate(pos)
        p.d.insert(i, ch)
        p.size += 1
        self.split(p)

    def erase(self, pos):
        p, i = self._locate(pos)
        del p.d[i]
        p.size -= 1
        if p.size == 0:
            self._remove_node(p)

    def _remove_node(self, x):
        p = self.head
        if p is x:
            self.head = p.nxt
            return
        while p is not None and p.nxt is not x:
            p = p.nxt
        if p is not None:
            p.nxt = x.nxt

    def _size(self):
        p = self.head
        s = 0
        while p is not None:
            s += p.size
            p = p.nxt
        return s

    def to_str(self):
        p = self.head
        out = []
        while p is not None:
            out.extend(p.d)
            p = p.nxt
        return "".join(out)


if __name__ == "__main__":
    import random

    random.seed(7)
    bl = BlockList("hello")
    brute = list("hello")
    for _ in range(2000):
        op = random.random()
        if op < 0.45 and len(brute) > 0:
            pos = random.randrange(len(brute))
            bl.erase(pos)
            del brute[pos]
        elif op < 0.85:
            pos = random.randrange(len(brute) + 1)
            ch = chr(random.randint(97, 122))
            bl.insert(pos, ch)
            brute.insert(pos, ch)
        elif len(brute) > 0:
            pos = random.randrange(len(brute))
            assert bl.find(pos) == brute[pos], (pos, bl.find(pos), brute[pos])
    assert bl.to_str() == "".join(brute)
    # 大量插入使块分裂后依然正确
    for i in range(5000):
        bl.insert(i % (i + 1), "x")
    assert bl._size() == 5000 + len(brute)
    print("block-list 自测通过：2000+ 次随机 插入/删除/查找 与列表对拍一致")
